[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <ex:ritofngmsTAPP-P0> ;
            sh:resultMessage "Core requires bios:computationalTool on the procedure." ;
            sh:resultPath bios:computationalTool ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "Core requires bios:computationalTool on the procedure." ;
                    sh:minCount 1 ;
                    sh:path bios:computationalTool ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <ex:ritofngmsTAPP-P0> ;
            sh:resultMessage "Core requires ada:analyticalMode on the procedure." ;
            sh:resultPath ada:analyticalMode ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "Core requires ada:analyticalMode on the procedure." ;
                    sh:minCount 1 ;
                    sh:path ada:analyticalMode ;
                    sh:severity sh:Warning ] ] .

